// 入力: { kind: 'members'|'pcs'|'servers', id, patch, reason?, replace?, attempt? }
// 出力: { ok, path, commitSha, action }
//
// bot が書けるのは state/ のみ(desired は人が PR で編集する)。
// 競合時は attempt を増やして自分自身を呼び直す(楽観的排他+リトライ)。
// 設計: docs/design/03-service-catalog.md#並行書き込みの制御

const inp = $input.first()?.json ?? {};

const DIRS = { members: 'state/members', pcs: 'state/pcs', servers: 'state/servers' };
const dir = DIRS[inp.kind];
if (!dir) {
  throw new Error(`ledger-write: 不正な kind: ${JSON.stringify(inp.kind)}(有効値: ${Object.keys(DIRS).join(', ')})`);
}
if (!inp.id || typeof inp.id !== 'string') throw new Error('ledger-write: id は必須です');
if (!inp.patch || typeof inp.patch !== 'object') throw new Error('ledger-write: patch(オブジェクト)は必須です');
if (!/^[a-z0-9][a-z0-9._-]*$/i.test(inp.id)) throw new Error(`ledger-write: id に使えない文字が含まれます: ${inp.id}`);

const repo = $env.LEDGER_REPO;
if (!repo) throw new Error('ledger-write: LEDGER_REPO が未設定です');

const path = `${dir}/${inp.id}.yaml`;
return [{ json: {
  repo,
  path,
  url: `https://api.github.com/repos/${repo}/contents/${path}`,
  kind: inp.kind,
  id: inp.id,
  patch: inp.patch,
  replace: inp.replace === true,
  reason: inp.reason ?? '',
  attempt: Number(inp.attempt ?? 1),
  maxAttempts: 3,
}}];

// 既存内容に patch をマージして本文を作る。
// 404(新規作成)の場合は空から作る。sha を付けることで、
// 読み取り後に他の実行が書き込んでいたら GitHub 側が 409 を返す(楽観的排他)。

const YAML = require('yaml');
const ctx = $('書き込み対象を決める').first().json;
const res = $input.first()?.json ?? {};

let base = {};
let sha = null;
if (res && res.encoding === 'base64' && typeof res.content === 'string') {
  base = YAML.parse(Buffer.from(res.content, 'base64').toString('utf8')) ?? {};
  sha = res.sha;
}

// プレーンオブジェクトのみ再帰マージ。配列は丸ごと置換(予測しやすさを優先)。
// patch の値が null のキーは削除する(RFC 7386 JSON Merge Patch と同じ規約)。
// 解消済みの失敗記録などを消せるようにするため。
const isPlain = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const merge = (a, b) => {
  const out = { ...a };
  for (const [k, v] of Object.entries(b)) {
    if (v === null) { delete out[k]; continue; }
    out[k] = isPlain(v) && isPlain(a?.[k]) ? merge(a[k], v) : v;
  }
  return out;
};

const next = ctx.replace ? ctx.patch : merge(base, ctx.patch);
const text = YAML.stringify(next);

const head = `state(${ctx.kind}): ${ctx.id}`;
const message = ctx.reason ? `${head} — ${ctx.reason}` : head;

return [{ json: {
  url: ctx.url,
  body: {
    message,
    content: Buffer.from(text, 'utf8').toString('base64'),
    ...(sha ? { sha } : {}),
  },
  existed: Boolean(sha),
}}];

// 成功。呼び出し側にはコミット SHA を返す(監査・追跡用)。
const ctx = $('書き込み対象を決める').first().json;
const merged = $('マージして本文を作る').first().json;
const res = $input.first().json;

return [{ json: {
  ok: true,
  path: ctx.path,
  action: merged.existed ? 'updated' : 'created',
  commitSha: res.commit?.sha ?? null,
  attempts: ctx.attempt,
}}];

// 失敗。競合(409/422)なら読み直して再試行するため、自分自身を呼ぶ入力を作る。
// それ以外(権限不足など)は即座に失敗させる — 再試行しても直らないため。
const ctx = $('書き込み対象を決める').first().json;
const res = $input.first().json;

const status = res.error?.status ?? res.status ?? res.error?.httpCode ?? null;
const message = res.error?.message ?? res.message ?? JSON.stringify(res).slice(0, 200);
const conflict = [409, 422].includes(Number(status)) || /sha|conflict/i.test(String(message));

if (!conflict) {
  throw new Error(`ledger-write: ${ctx.path} の書き込みに失敗 (status=${status}): ${message}`);
}
if (ctx.attempt >= ctx.maxAttempts) {
  throw new Error(`ledger-write: ${ctx.path} が ${ctx.maxAttempts} 回とも競合しました。日次リコンサイルで再試行されます`);
}

return [{ json: {
  kind: ctx.kind,
  id: ctx.id,
  patch: ctx.patch,
  replace: ctx.replace,
  reason: ctx.reason,
  attempt: ctx.attempt + 1,
}}];
